'use client';

import * as React from 'react';
import { useParams, useRouter, useSearchParams } from 'next/navigation';
import { useEffect, useState, useRef } from 'react';
import { ClientAuthService as AuthService, ClientMessagingService as MessagingService } from '@/services/client-api.service';
import { Loader2, MessageCircle, Send, X, Bell, Edit, Trash2, Flag } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import { formatDate } from '@/lib/utils';

export const ChatView: React.FC = () => {
  const { conversationId } = useParams<{ conversationId: string }>();
  const router = useRouter();
  const searchParams = useSearchParams();

  const [messages, setMessages] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [conversation, setConversation] = useState<any>(null);
  const [messageInput, setMessageInput] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [scrollToBottom, setScrollToBottom] = useState<boolean>(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // For editing messages
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [editMessageContent, setEditMessageContent] = useState<string>('');

  // Load conversation and messages
  const loadConversation = async () => {
    try {
      setLoading(true);
      setError(null);
      const user = await AuthService.getCurrentUser();
      if (!user) {
        router.push('/auth/signin');
        return;
      }

      if (!conversationId) {
        setError('Conversation ID is required');
        return;
      }

      // Load conversation details
      const convData = await MessagingService.getConversationById(conversationId);
      setConversation(convData);

      // Load messages
      const msgData = await MessagingService.getMessages(conversationId, 1, 50);
      setMessages(msgData);
      setScrollToBottom(true);
    } catch (err: any) {
      setError(err.message || 'Failed to load conversation');
    } finally {
      setLoading(false);
    }
  };

  // Load initial data
  useEffect(() => {
    loadConversation();
  }, [conversationId, searchParams]);

  // Scroll to bottom when messages change or scrollToBottom flag is set
  useEffect(() => {
    if (scrollToBottom && messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
      setScrollToBottom(false);
    }
  }, [messages, scrollToBottom]);

  // Handle sending a message
  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!messageInput.trim()) {
      return;
    }

    setIsLoading(true);
    try {
      const newMessage = await MessagingService.sendMessage(
        conversationId,
        messageInput,
      );

      // Add the new message to the list
      setMessages(prev => [...prev, newMessage]);
      setMessageInput('');
      setScrollToBottom(true);
    } catch (err: any) {
      setError(err.message || 'Failed to send message');
    } finally {
      setIsLoading(false);
    }
  };

  // Handle marking messages as read
  const handleMarkAsRead = async () => {
    try {
      await MessagingService.markMessageAsRead(messages[messages.length - 1]?.id || '');
      // In a real app, we'd update the UI to show messages as read
    } catch (err: any) {
      console.error('Failed to mark as read:', err);
    }
  };

  // Handle editing a message
  const handleEditMessage = async (messageId: string, message: any) => {
    setEditingMessageId(messageId);
    setEditMessageContent(message.content);
  };

  const handleSaveEdit = async (messageId: string) => {
    if (!editMessageContent.trim()) {
      return;
    }

    setIsLoading(true);
    try {
      const updatedMessage = await MessagingService.editMessage(messageId, editMessageContent);

      // Update the message in the list
      setMessages(prev => 
        prev.map(msg => msg.id === messageId ? updatedMessage : msg)
      );

      setEditingMessageId(null);
      setEditMessageContent('');
    } catch (err: any) {
      setError(err.message || 'Failed to edit message');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCancelEdit = () => {
    setEditingMessageId(null);
    setEditMessageContent('');
  };

  // Handle deleting a message
  const handleDeleteMessage = async (messageId: string) => {
    if (!window.confirm('Are you sure you want to delete this message?')) {
      return;
    }

    setIsLoading(true);
    try {
      await MessagingService.deleteMessage(messageId);

      // Remove the message from the list
      setMessages(prev => prev.filter(msg => msg.id !== messageId));
    } catch (err: any) {
      setError(err.message || 'Failed to delete message');
    } finally {
      setIsLoading(false);
    }
  };

  // Handle reporting a message
  const handleReportMessage = async (messageId: string) => {
    // In a real app, we'd show a modal for reporting
    // For now, we'll just call the API with a placeholder reason
    try {
      await MessagingService.reportMessage(messageId, 'Inappropriate content', 'This message violates community guidelines');
      alert('Message reported successfully');
    } catch (err: any) {
      setError(err.message || 'Failed to report message');
    }
  };

  if (loading) {
    return (
      <div className="min-h-[calc(100vh-14rem)]">
        <div className="flex h-full w-full items-center justify-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-[calc(100vh-14rem)]">
        <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-6">
          <h3 className="text-lg font-medium mb-4">{error}</h3>
          <p className="text-gray-600">
            Please try again or contact support if the issue persists.
          </p>
          <div className="mt-4">
            <Button onClick={loadConversation}>Try Again</Button>
          </div>
        </div>
      </div>
    );
  }

  if (!conversation) {
    return (
      <div className="min-h-[calc(100vh-14rem)]">
        <div className="flex h-full w-full items-center justify-center">
          <p className="text-gray-500">Loading conversation...</p>
        </div>
      </div>
    );
  }

  // Get other participants
  const otherMembers = conversation.conversation_members
    .filter((m: any) => m.user_id !== conversation.conversation_members[0]?.users.id)
    .map((m: any) => m.users);

  return (
    <div className="min-h-[calc(100vh-14rem)] flex flex-col">
      {/* Header */}
      <header className="border-b pb-4">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
            <div className="mb-4 sm:mb-0">
              <h1 className="text-xl font-bold text-gray-900">
                Conversation
                {otherMembers.length > 0 && (
                  <span className="ml-2 inline-flex h-6 w-6 items-center justify-center rounded-full bg-slate-200 text-xs font-medium text-slate-600">
                    {otherMembers.map((m: any) => `${m.first_name} ${m.last_name}`).join(', ') || 'Unknown User'}
                  </span>
                )}
              </h1>
            </div>
            <div className="flex items-center gap-3">
              <Button variant="outline" size="sm">
                <Bell className="w-4 h-4" />
              </Button>
              <Button variant="outline" size="sm" onClick={() => router.push('/messages')}>
                <X className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </div>
      </header>

      {/* Messages List */}
      <div className="flex-1 overflow-y-auto p-4">
        {messages.length === 0 ? (
          <div className="text-center py-12">
            <MessageCircle className="h-10 w-10 text-slate-400 mx-auto mb-4" />
            <p className="text-lg font-medium text-gray-900 mb-2">No messages yet</p>
            <p className="text-gray-600">
              Start the conversation by sending a message below.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {messages.map((message: any) => {
              const isOwnMessage = message.sender_id === conversation.conversation_members[0]?.users.id;
              const isEdited = !!message.edited_at;
              const isDeleted = !!message.deleted_at;

              return (
                <div key={message.id} className={cn(
                  'flex',
                  isOwnMessage ? 'justify-end' : 'justify-start'
                )}>
                  {!isDeleted && (
                    <div className={cn(
                      'max-w-[80%]',
                      isOwnMessage ? 'bg-blue-500 text-white' : 'bg-slate-200 text-slate-900',
                      'rounded-lg p-3'
                    )}>
                      <div className="flex-1">
                        <p className="whitespace-pre-wrap break-words">
                          {message.content}
                        </p>
                        {isEdited && (
                          <p className="text-xs text-slate-500 mt-1">
                            Edited
                          </p>
                        )}
                      </div>
                      <div className="text-xs text-slate-400 mt-1">
                        {new Date(message.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>

                      {/* Message actions (for own messages) */}
                      {isOwnMessage && !isDeleted && (
                        <div className="flex space-x-2 mt-2">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleEditMessage(message.id, message)}
                          >
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDeleteMessage(message.id)}
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleReportMessage(message.id)}
                          >
                            <Flag className="w-4 h-4" />
                          </Button>
                        </div>
                      )}
                    </div>
                  )}

                  {isDeleted && (
                    <div className="text-xs text-slate-400 italic">
                      This message was deleted
                    </div>
                  )}
                </div>
              );
            })}
            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Message Input */}
      <form onSubmit={handleSendMessage} className="flex p-4 border-t border-slate-200">
        {editingMessageId ? (
          <>
            <Input
              value={editMessageContent}
              onChange={(e) => setEditMessageContent(e.target.value)}
              placeholder="Edit your message..."
              className="flex-1"
            />
            <Button 
              onClick={() => handleSaveEdit(editingMessageId)}
              isLoading={isLoading}
              disabled={isLoading || !editMessageContent.trim()}
            >
              {isLoading ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Send className="w-4 h-4" />
              )}
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={handleCancelEdit}
              className="ml-2"
            >
              Cancel
            </Button>
          </>
        ) : (
          <>
            <Input
              value={messageInput}
              onChange={(e) => setMessageInput(e.target.value)}
              placeholder="Type a message..."
              className="flex-1"
            />
            <Button 
              onClick={handleSendMessage}
              isLoading={isLoading}
              disabled={isLoading || !messageInput.trim()}
            >
              {isLoading ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Send className="w-4 h-4" />
              )}
            </Button>
          </>
        )}
      </form>
    </div>
  );
};

'use client';

import * as React from 'react';
import Link from 'next/link';
import { useSearchParams, useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import { ClientAuthService as AuthService, ClientMessagingService as MessagingService } from '@/services/client-api.service';
import { Bell, Loader2, MessageCircle, Users, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export interface Conversation {
  id: string;
  conversation_type: string;
  job_id: string | null;
  proposal_id: string | null;
  contract_id: string | null;
  title: string | null;
  last_message_at: string;
  created_at: string;
  updated_at: string;
  last_read_at: string | null;
  is_muted: boolean;
  joined_at: string;
  // Populated from the join
  conversation_members: {
    user_id: string;
    member_role: string;
    last_read_at: string | null;
    joined_at: string;
    users: {
      id: string;
      email: string;
      profiles: {
        first_name: string;
        last_name: string;
        display_name: string;
        avatar_url: string | null;
      };
    }[];
  }[];
}

export const ConversationList: React.FC = () => {
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [unreadCount, setUnreadCount] = useState<number>(0);
  const [refreshing, setRefreshing] = useState<boolean>(false);
  const router = useRouter();
  const searchParams = useSearchParams();

  // Load conversations
  const loadConversations = async () => {
    try {
      setLoading(true);
      setError(null);
      const user = await AuthService.getCurrentUser();
      if (!user) {
        router.push('/auth/signin');
        return;
      }

      const data = await MessagingService.getUserConversations();
      setConversations(data as Conversation[]);

      // Get unread count
      const count = await MessagingService.getUnreadMessageCount();
      setUnreadCount(count);
    } catch (err: any) {
      setError(err.message || 'Failed to load conversations');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  // Load initial data
  useEffect(() => {
    loadConversations();
  }, [searchParams]);

  // Handle refresh
  const handleRefresh = async () => {
    setRefreshing(true);
    await loadConversations();
  };

  // Handle navigation to conversation
  const handleConversationClick = (conversationId: string) => {
    router.push(`/messages/${conversationId}`);
  };

  if (loading) {
    return (
      <div className="min-h-[calc(100vh-14rem)] py-8">
        <div className="max-w-4xl mx-auto">
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
            <p className="ml-4 text-lg">Loading conversations...</p>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-[calc(100vh-14rem)] py-8">
        <div className="max-w-4xl mx-auto">
          <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-6">
            <h3 className="text-lg font-medium mb-4">{error}</h3>
            <p className="text-gray-600">
              Please try again or contact support if the issue persists.
            </p>
            <div className="mt-4">
              <Button onClick={loadConversations}>Try Again</Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-[calc(100vh-14rem)]">
      {/* Header */}
      <div className="border-b pb-6">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between">
            <div className="mb-4 sm:mb-0">
              <h1 className="text-2xl font-bold text-gray-900">
                Messages
                {unreadCount > 0 && (
                  <span className="ml-2 inline-flex h-6 w-6 items-center justify-center rounded-full bg-red-500 text-xs font-medium text-white">
                    {unreadCount}
                  </span>
                )}
              </h1>
            </div>
            <div className="flex items-center gap-3">
              <Button
                variant="outline"
                onClick={handleRefresh}
                className={cn(refreshing && 'animate-spin')}
              >
                {refreshing ? 'Refreshing' : 'Refresh'}
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Conversations List */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-8">
        {conversations.length === 0 ? (
          <div className="text-center py-12">
            <MessageCircle className="h-10 w-10 text-slate-400 mx-auto mb-4" />
            <p className="text-lg font-medium text-gray-900 mb-2">No conversations yet</p>
            <p className="text-gray-600">
              Start a conversation by visiting a job or consultant profile and clicking
              the "Message" button.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-slate-200">
            {conversations.map((conversation) => {
              // Get the other participant(s) in the conversation
              const otherMembers = conversation.conversation_members
                .filter((m: any) => m.user_id !== conversation.conversation_members[0]?.users?.[0]?.id)
                .map((m: any) => m.users);

              // Get the last message (we'd need to fetch this separately in a real app)
              // For now, we'll just show placeholder
              const lastMessagePreview = 'Last message preview...';
              const lastMessageTime = new Date(conversation.last_message_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

              // Check if conversation has unread messages
              const hasUnread = !conversation.last_read_at || 
                new Date(conversation.last_message_at) > new Date(conversation.last_read_at || conversation.last_message_at);

              return (
                <Link
                  key={conversation.id}
                  href={`/messages/${conversation.id}`}
                  onClick={() => handleConversationClick(conversation.id)}
                  className={cn(
                    'flex p-4 hover:bg-slate-50',
                    hasUnread && 'bg-slate-50'
                  )}
                >
                  <div className="flex-shrink-0">
                    {otherMembers.length > 0 ? (
                      <div className="flex h-10 w-10 items-center justify-center rounded-full bg-slate-200 text-slate-500">
                        {otherMembers[0].first_name?.charAt(0) || 'U'}
                        {otherMembers[0].last_name?.charAt(0) || ''}
                      </div>
                    ) : (
                      <div className="flex h-10 w-10 items-center justify-center rounded-full bg-slate-200 text-slate-500">
                        {'?'}
                      </div>
                    )}
                  </div>
                  <div className="flex-1 ml-4 space-y-1">
                    <div className="flex justify-between">
                      <div className="flex-1">
                        <p className="text-sm font-medium text-gray-900">
                          {otherMembers.map((m: any) => `${m.first_name} ${m.last_name}`).join(', ') || 'Unknown User'}
                        </p>
                        <p className="text-sm text-slate-500 line-clamp-1">
                          {lastMessagePreview}
                        </p>
                      </div>
                      <div className="text-right text-xs">
                        <p className={cn(
                          hasUnread ? 'font-medium text-gray-900' : 'text-slate-400'
                        )}>
                          {lastMessageTime}
                        </p>
                        {hasUnread && (
                          <div className="ml-2 inline-flex h-5 w-5 items-center justify-center rounded-full bg-blue-500 text-xs font-medium text-white">
                            ●
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </Link>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

'use client';

import { useEffect, useState } from 'react';
import { ClientProfileService as ProfileService } from '@/services/client-api.service';
import { CertificationBadge } from '@/components/profiles/certification-badge';
import { certificationFormSchema } from '@/lib/validations/profile.schemas';
import { z } from 'zod';
import { cn } from '@/lib/utils';

interface CertificationManagerProps {
  consultantId: string;
  onUpdate?: () => void;
}

export default function CertificationManager({ consultantId, onUpdate }: CertificationManagerProps) {
  const [certifications, setCertifications] = useState<any[]>([]);
  const [allCertifications, setAllCertifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);

  // Form state for adding new certification
  const [formData, setFormData] = useState({
    certification_id: '',
    custom_name: '',
    credential_id: '',
    issue_date: '',
    expiry_date: '',
    verification_document_url: '',
  });

  // Fetch data
  useEffect(() => {
    loadData();
  }, [consultantId]);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);

      // Get consultant's current certifications
      const consultantCertifications = await ProfileService.getConsultantCertifications(consultantId);
      setCertifications(consultantCertifications);

      // Get all available certifications
      // For now, we'll get a static list or leave empty - in a real app this would come from database
      setAllCertifications([]);

    } catch (err: any) {
      console.error('Error loading certifications data:', err);
      setError(err.message || 'Failed to load certifications data');
    } finally {
      setLoading(false);
    }
  }

  // Handle form input changes
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setIsAdding(true);
    setError(null);

    try {
      // Validate form data
      const validatedData = certificationFormSchema.parse(formData);

      // Add certification to consultant
      await ProfileService.addConsultantCertification(consultantId, {
        certification_id: validatedData.certificationId || undefined,
        custom_name: validatedData.customName,
        credential_id: validatedData.credentialId,
        issue_date: validatedData.issueDate,
        expiry_date: validatedData.expiryDate,
        verification_document_url: validatedData.verificationDocumentUrl,
      });

      // Reset form
      setFormData({
        certification_id: '',
        custom_name: '',
        credential_id: '',
        issue_date: '',
        expiry_date: '',
        verification_document_url: '',
      });

      // Reload data
      await loadData();

      // Notify parent to update
      if (onUpdate) onUpdate();

    } catch (err: any) {
      if (err instanceof z.ZodError) {
        setError('Please fix the errors in the form');
      } else {
        console.error('Error adding certification:', err);
        setError(err.message || 'Failed to add certification');
      }
    } finally {
      setIsAdding(false);
    }
  }

  // Handle certification removal
  async function handleRemove(certificationId: string) {
    if (!window.confirm('Are you sure you want to remove this certification?')) return;

    try {
      // In a real implementation, we'd have a remove method
      // For now, we'll just show a message
      alert('Certification removal would be implemented here');

    } catch (err: any) {
      console.error('Error removing certification:', err);
      setError(err.message || 'Failed to remove certification');
    }
  }

  if (loading) {
    return (
      <div className="text-center py-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500 mx-auto mb-4"></div>
        <p>Loading certifications...</p>
