      </div>

      {/* Add Certification Form */}
      {isAdding && (
        <div className="border-t border-gray-200 pt-6">
          <h3 className="text-md font-medium text-gray-900 mb-4">Add New Certification</h3>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
