  draft: 'Draft',
  submitted: 'Submitted',
  shortlisted: 'Shortlisted',
  rejected: 'Rejected',
  withdrawn: 'Withdrawn',
  accepted: 'Accepted',
};

export default function ProposalCard({
  proposal,
  currentUserRole,
  onWithdraw,
  onShortlist,
  onReject,
  onAccept,
  className = '',
}: ProposalCardProps) {
  const {
    id,
    status,
    proposed_duration_weeks,
    proposed_price_cents,
    submitted_at,
    consultant,
    job,
  } = proposal;

  const consultantName = consultant?.profiles?.display_name || consultant?.profiles?.first_name || 'Unknown';

