type Participant = { isClient: boolean; isConsultant: boolean };

export class ContractService extends BaseService {
  private static async participant(contract: any, userId: string): Promise<Participant> {
    const db = createAdminClient();
    const [{ data: client }, { data: consultant }] = await Promise.all([
      db.from('client_profiles').select('user_id').eq('id', contract.client_id).single(),
      db.from('consultant_profiles').select('user_id').eq('id', contract.consultant_id).single(),
    ]);
    return { isClient: client?.user_id === userId, isConsultant: consultant?.user_id === userId };
  }

  private static async getRaw(id: string) {
    const { data, error } = await createAdminClient().from('contracts').select('*').eq('id', id).single();
    if (error || !data) throw new NotFoundError('Contract');
    return data;
  }

  static async createContract(clientUserId: string, input: CreateContractData): Promise<Contract> {
    try {
      const db = createAdminClient();
      const { data: proposal } = await db.from('proposals').select('id, job_id, consultant_id, status, proposed_price_cents').eq('id', input.proposal_id).single();
      if (!proposal) throw new NotFoundError('Proposal');
      if (!['shortlisted', 'accepted'].includes(proposal.status)) throw new ForbiddenError('Only a shortlisted proposal can become a contract.');

      const { data: job } = await db.from('jobs').select('id, client_id, title, status').eq('id', proposal.job_id).single();
      if (!job) throw new NotFoundError('Job');
      const { data: client } = await db.from('client_profiles').select('id, user_id').eq('id', job.client_id).single();
      if (client?.user_id !== clientUserId) throw new ForbiddenError('Only the job owner can create this contract.');

      const { data: duplicate } = await db.from('contracts').select('id').eq('proposal_id', input.proposal_id).maybeSingle();
      if (duplicate) throw new ConflictError('This proposal already has a contract.');
      const type = input.contract_type;
      const total = input.total_amount_cents ?? proposal.proposed_price_cents;
      if (!Number.isInteger(total) || total <= 0) throw new ValidationError('A positive total amount is required.');

      const { data: contract, error } = await db.from('contracts').insert({
        proposal_id: proposal.id, job_id: job.id, client_id: job.client_id, consultant_id: proposal.consultant_id,
        title: input.title, terms_markdown: input.terms_markdown, contract_type: type,
        payment_structure: type === 'hourly' ? 'hourly_capped' : 'fixed_milestones',
        total_amount_cents: total, start_date: input.start_date || null, end_date: input.end_date || null,
        status: 'pending_acceptance',
      }).select('*').single();
      if (error || !contract) throw new AppError('Failed to create contract.', 500, 'DB_INSERT_ERROR', error);

      // Hiring is completed as part of contract creation. The job update is deliberately
      // limited to workflow state; no payment provider call occurs here.
      await db.from('proposals').update({ status: 'accepted', updated_at: new Date().toISOString() }).eq('id', proposal.id);
      await db.from('jobs').update({ status: 'hired', hired_at: new Date().toISOString(), updated_at: new Date().toISOString() }).eq('id', job.id);
      return contract as Contract;
    } catch (error) {
      if (error instanceof AppError) throw error;
      this.handleError(error, 'ContractService.createContract');
    }
  }

  static async getContract(id: string, userId: string): Promise<Contract> {
    const contract = await this.getRaw(id);
    const actor = await this.participant(contract, userId);
    if (!actor.isClient && !actor.isConsultant) throw new ForbiddenError('You do not have access to this contract.');
    return contract as Contract;
  }

  static async listContracts(userId: string): Promise<Contract[]> {
    const db = createAdminClient();
    const [{ data: client }, { data: consultant }] = await Promise.all([
      db.from('client_profiles').select('id').eq('user_id', userId).maybeSingle(),
      db.from('consultant_profiles').select('id').eq('user_id', userId).maybeSingle(),
    ]);
    let query = db.from('contracts').select('*').order('created_at', { ascending: false });
    if (client?.id) query = query.eq('client_id', client.id);
    else if (consultant?.id) query = query.eq('consultant_id', consultant.id);
    else return [];
    const { data, error } = await query;
    if (error) throw new AppError('Failed to fetch contracts.', 500, 'DB_FETCH_ERROR', error);
    return (data || []) as Contract[];
  }

  static async transitionContract(id: string, userId: string, next: ContractStatus): Promise<Contract> {
    const db = createAdminClient();
    const contract = await this.getRaw(id);
    const actor = await this.participant(contract, userId);
    if (!actor.isClient && !actor.isConsultant) throw new ForbiddenError('You do not have access to this contract.');
    const current = contract.status as ContractStatus;
    if (!CONTRACT_TRANSITIONS[current]?.includes(next)) throw new ConflictError(`Invalid contract transition: ${current} -> ${next}.`);
    const clientOnly = ['active', 'completed', 'cancelled', 'terminated'].includes(next);
    if (clientOnly && !actor.isClient) throw new ForbiddenError('Only the client can perform this contract transition.');
    if (next === 'disputed' && !actor.isClient && !actor.isConsultant) throw new ForbiddenError('Only contract participants can dispute a contract.');
    const payload: any = { status: next, updated_at: new Date().toISOString() };
    if (next === 'active') payload.started_at = new Date().toISOString();
    if (next === 'completed') payload.completed_at = new Date().toISOString();
    if (['cancelled', 'terminated'].includes(next)) payload.cancelled_at = new Date().toISOString();
    const { data, error } = await db.from('contracts').update(payload).eq('id', id).select('*').single();
    if (error || !data) throw new AppError('Failed to transition contract.', 500, 'DB_UPDATE_ERROR', error);
    return data as Contract;
  }

  static async createMilestone(userId: string, input: { contract_id: string; title: string; description?: string; amount_cents: number; due_date: string; sequence_order: number }): Promise<Milestone> {
    const db = createAdminClient();
    const contract = await this.getRaw(input.contract_id);
    const actor = await this.participant(contract, userId);
    if (!actor.isClient) throw new ForbiddenError('Only the client can manage contract milestones.');
    if ((contract.contract_type || (contract.payment_structure === 'hourly_capped' ? 'hourly' : 'fixed_price')) !== 'fixed_price') throw new ForbiddenError('Milestones are only available for fixed-price contracts.');
    if (contract.status !== 'pending_acceptance' && contract.status !== 'active') throw new ForbiddenError('Milestones cannot be added to this contract.');
    const { data: milestone, error } = await db.from('milestones').insert({ ...input, description: input.description || '', status: 'pending' }).select('*').single();
    if (error || !milestone) throw new AppError('Failed to create milestone.', 500, 'DB_INSERT_ERROR', error);
    return milestone as Milestone;
  }

  static async transitionMilestone(id: string, userId: string, next: MilestoneStatus, note?: string): Promise<Milestone> {
    const db = createAdminClient();
    const { data: milestone } = await db.from('milestones').select('*').eq('id', id).single();
    if (!milestone) throw new NotFoundError('Milestone');
    const contract = await this.getRaw(milestone.contract_id);
    const actor = await this.participant(contract, userId);
    if (!actor.isClient && !actor.isConsultant) throw new ForbiddenError('You do not have access to this milestone.');
    const current = milestone.status as MilestoneStatus;
    if (!MILESTONE_TRANSITIONS[current]?.includes(next)) throw new ConflictError(`Invalid milestone transition: ${current} -> ${next}.`);
    if (next === 'funded' && !actor.isClient) throw new ForbiddenError('Only the client can fund a milestone.');
    if (next === 'in_progress' && !actor.isConsultant) throw new ForbiddenError('Only the assigned consultant can start work.');
    if (next === 'submitted' && !actor.isConsultant) throw new ForbiddenError('Only the assigned consultant can submit deliverables.');
    if (next === 'approved' && !actor.isClient) throw new ForbiddenError('Only the client can approve a milestone.');
    const payload: any = { status: next, updated_at: new Date().toISOString() };
    if (next === 'submitted') { payload.submitted_at = new Date().toISOString(); if (note) payload.deliverable_notes = note; }
    if (next === 'approved') payload.approved_at = new Date().toISOString();
    if (next === 'disputed' && note) payload.revision_notes = note;
    const { data, error } = await db.from('milestones').update(payload).eq('id', id).select('*').single();
    if (error || !data) throw new AppError('Failed to transition milestone.', 500, 'DB_UPDATE_ERROR', error);
    return data as Milestone;
  }

  static async updateMilestone(id: string, userId: string, updates: Record<string, unknown>): Promise<Milestone> {
    const db = createAdminClient();
    const { data: milestone } = await db.from('milestones').select('*').eq('id', id).single();
    if (!milestone) throw new NotFoundError('Milestone');
    const contract = await this.getRaw(milestone.contract_id);
    const actor = await this.participant(contract, userId);
    if (!actor.isClient) throw new ForbiddenError('Only the client can edit milestone terms.');
    if (['funded', 'in_progress', 'submitted', 'approved', 'disputed'].includes(milestone.status)) throw new ForbiddenError('Milestone terms cannot be changed after funding.');
    const { data: payment } = await db.from('payments').select('id').eq('milestone_id', id).in('status', ['held_in_escrow', 'released']).maybeSingle();
    if (payment) throw new ForbiddenError('Milestone amount cannot be changed after funding.');
    const { data, error } = await db.from('milestones').update({ ...updates, updated_at: new Date().toISOString() }).eq('id', id).select('*').single();
    if (error || !data) throw new AppError('Failed to update milestone.', 500, 'DB_UPDATE_ERROR', error);
    return data as Milestone;
  }
}

import { createClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';
import type { Job, JobStatus, BudgetType, IntegrationType, ComplexityTier, ThroughputTier } from '@/types/database';
import { AppError } from '@/lib/errors';

export class JobService {
  /**
   * Get a job by ID
   */
  static async getJobById(id: string): Promise<Job | null> {
    try {
      const supabase = await createClient();
      const { data: job, error } = await supabase
        .from('jobs')
        .select('*')
        .eq('id', id)
        .single();
      if (error) {
        console.error('[DB Error - Get Job By ID]:', error);
        return null;
      }
      return job;
    } catch (error) {
      console.error('[JobService.getJobById]:', error);
      return null;
    }
  }

  /**
   * Get client ID by user ID
   */
  static async getClientIdByUserId(userId: string): Promise<string | null> {
    try {
      const supabase = await createClient();
      const { data: clientProfile, error } = await supabase
        .from('client_profiles')
        .select('id, company_id')
        .eq('user_id', userId)
        .single();
      if (error) {
        console.error('[DB Error - Get Client Profile By User ID]:', error);
        return null;
      }
      return clientProfile?.id ?? null;
    } catch (error) {
      console.error('[JobService.getClientIdByUserId]:', error);
      return null;
    }
  }

  /**
   * Get jobs with filtering and pagination
   */
  static async getJobs(options: {
    page?: number;
    limit?: number;
    search?: string;
    sapProducts?: string[];
    sourceSystems?: string[];
    targetSystems?: string[];
    integrationTypes?: string[];
    protocols?: string[];
    budgetMin?: number;
    budgetMax?: number;
    experienceMin?: number;
    projectType?: string;
    status?: JobStatus[];
    sortBy?: string;
    sortOrder?: 'asc' | 'desc';
  }): Promise<{ jobs: Job[]; total: number; page: number; limit: number }> {
    try {
      const supabase = await createClient();
      const page = options.page ?? 1;
      const limit = options.limit ?? 10;
      const from = (page - 1) * limit;
      const to = from + limit - 1;

      let query = supabase
        .from('jobs')
        .select('*', { count: 'exact' });

      // Search
      if (options.search) {
        const searchTerm = `%${options.search}%`;
        query = query.or(`title.ilike.${searchTerm},description_markdown.ilike.${searchTerm}`);
      }

      // SAP Products - not stored in jobs table; ignore for now
      // if (options.sapProducts?.length) {
      //   // TODO: Implement if sap_products relation exists
      // }

      // Source Systems
      if (options.sourceSystems?.length) {
        // Assuming source_systems is a text array; we need to check overlap?
        // For simplicity, we'll require all selected source systems to be present.
        // Use contains for each? Actually we want jobs where source_systems contains all selected?
        // We'll implement as: source_systems contains each selected value.
        for (const system of options.sourceSystems) {
          query = query.contains('source_systems', [system]);
        }
      }

      // Target Systems
      if (options.targetSystems?.length) {
        for (const system of options.targetSystems) {
          query = query.contains('target_systems', [system]);
        }
      }

      // Integration Types
      if (options.integrationTypes?.length) {
        query = query.in('integration_type', options.integrationTypes);
      }

      // Protocols
      if (options.protocols?.length) {
        // Ensure job's protocols array contains all selected protocols
        for (const protocol of options.protocols) {
          query = query.contains('protocols', [protocol]);
        }
      }

      // Budget Min/Max - simplified: check budget_fixed_cents range (ignore budget_type complexity)
      if (options.budgetMin !== undefined) {
        query = query.gte('budget_fixed_cents', options.budgetMin);
      }
      if (options.budgetMax !== undefined) {
        query = query.lte('budget_fixed_cents', options.budgetMax);
      }

      // Experience Min
      if (options.experienceMin !== undefined) {
        query = query.gte('experience_required', options.experienceMin);
      }

      // Project Type
      if (options.projectType) {
        query = query.ilike('project_type', `%${options.projectType}%`);
      }

      // Status
      if (options.status?.length) {
        query = query.in('status', options.status);
      }

      // Sorting
      const sortBy = options.sortBy ?? 'created_at';
      const sortOrder = options.sortOrder ?? 'desc';
      query = query.order(sortBy, { ascending: sortOrder === 'asc' });

      // Pagination
      query = query.range(from, to);

      const { data, error, count } = await query;
      if (error) {
        console.error('[DB Error - Get Jobs]:', error);
        throw new AppError('Failed to fetch jobs', 500);
      }

      return {
        jobs: data as Job[],
        total: count ?? 0,
        page,
        limit,
      };
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('[JobService.getJobs]:', error);
      throw new AppError('Failed to fetch jobs', 500);
    }
  }

  /**
   * Create a new job
   */
  static async createJob(data: Omit<Job, 'id' | 'client_id' | 'company_id' | 'slug' | 'status' | 'views_count' | 'proposals_count' | 'hired_at' | 'expires_at' | 'created_at' | 'updated_at'>): Promise<Job> {
    try {
      const adminSupabase = createAdminClient();
      // Determine client_id from user? Actually the data should include client_id from the authenticated user.
      // We expect the caller to provide client_id in data? The create page does not pass client_id; it uses the current user's client profile.
      // We'll need to get the client_id from the user context. However, the service method signature does not include userId.
      // Looking at the create page, they call JobService.createJob with an object that does not include client_id.
      // They likely expect the service to infer the client_id from the current user.
      // We'll need to get the user ID and then get the client profile ID.
      // But we cannot rely on auth inside the service? We can use createClient to get user.
      // However, to avoid extra dependency, we can change the method to accept userId or clientId.
      // But to keep the existing call unchanged, we'll implement as: get the current user's client profile ID.
      // We'll use createClient to get the user, then get client profile.
      // This is acceptable because the service is server-side (route handler) and the user is authenticated.
      // We'll implement inside the method.

      const supabase = await createClient();
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        throw new AppError('Authentication required', 401);
      }

      const { data: clientProfile, error: clientProfileError } = await supabase
        .from('client_profiles')
        .select('id, company_id')
        .eq('user_id', user.id)
        .single();
      if (clientProfileError || !clientProfile) {
        throw new AppError('Client profile not found', 400);
      }

      const slugBase = data.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 80) || 'job';
      const jobData = {
        client_id: clientProfile.id,
        company_id: clientProfile.company_id,
        title: data.title,
        slug: `${slugBase}-${crypto.randomUUID()}`,
        integration_type: data.integration_type,
        source_systems: data.source_systems,
        target_systems: data.target_systems,
        protocols: data.protocols,
        expected_throughput_tier: data.expected_throughput_tier || 'moderate',
        complexity: data.complexity || 'moderate',
        description_markdown: data.description_markdown,
        deliverables_markdown: data.deliverables_markdown,
        estimated_duration_weeks: data.estimated_duration_weeks,
        budget_type: data.budget_type,
        budget_fixed_cents: data.budget_fixed_cents,
        budget_min_cents: data.budget_min_cents,
        budget_max_cents: data.budget_max_cents,
        status: 'draft',
        views_count: 0,
        proposals_count: 0,
        hired_at: null,
        expires_at: null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };

      const { data: job, error } = await adminSupabase
        .from('jobs')
        .insert(jobData)
        .select()
        .single();
      if (error) {
        console.error('[DB Error - Create Job]:', error);
        throw new AppError('Failed to create job', 500);
      }
      return job as Job;
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('[JobService.createJob]:', error);
      throw new AppError('Failed to create job', 500);
    }
  }

  /**
   * Update a job
   */
  static async updateJob(id: string, userId: string, data: Partial<Job>): Promise<Job> {
    try {
      const adminSupabase = createAdminClient();
      const { data: owner } = await adminSupabase.from('jobs').select('*, client_profiles!inner(user_id)').eq('id', id).single();
      if (!owner || (owner as any).client_profiles?.user_id !== userId) throw new AppError('You do not own this job', 403);
      const allowedFields = ['title', 'description_markdown', 'deliverables_markdown', 'integration_type', 'source_systems', 'target_systems', 'protocols', 'expected_throughput_tier', 'complexity', 'estimated_duration_weeks', 'budget_type', 'budget_fixed_cents', 'budget_min_cents', 'budget_max_cents', 'expires_at'];
      const updates = Object.fromEntries(Object.entries(data).filter(([key]) => allowedFields.includes(key)));
      if (data.status !== undefined) {
        const allowedStatus: Record<string, string[]> = { draft: ['open', 'cancelled'], open: ['closed', 'in_review'], in_review: ['closed'], hired: ['closed'] };
        if (!allowedStatus[owner.status]?.includes(data.status)) throw new AppError('Invalid job status transition', 409);
        updates.status = data.status;
      }
      const { data: job, error } = await adminSupabase
        .from('jobs')
        .update({
          ...updates,
          updated_at: new Date().toISOString(),
        })
        .eq('id', id)
        .select()
        .single();
      if (error) {
        console.error('[DB Error - Update Job]:', error);
        throw new AppError('Failed to update job', 500);
      }
      return job as Job;
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('[JobService.updateJob]:', error);
      throw new AppError('Failed to update job', 500);
    }
  }

  /**
   * Publish a job (change status from draft to open)
   */
  static async publishJob(id: string, userId: string): Promise<void> {
    try {
      const adminSupabase = createAdminClient();
      const { data: job, error: fetchError } = await adminSupabase
        .from('jobs')
        .select('status, client_profiles!inner(user_id)')
        .eq('id', id)
        .single();
      if (fetchError || !job || (job as any).client_profiles?.user_id !== userId) {
        throw new AppError('Job not found', 404);
      }
      if (job.status !== 'draft') {
        throw new AppError('Only draft jobs can be published', 400);
      }
      const { error } = await adminSupabase
        .from('jobs')
        .update({ status: 'open', updated_at: new Date().toISOString() })
        .eq('id', id);
      if (error) {
        console.error('[DB Error - Publish Job]:', error);
        throw new AppError('Failed to publish job', 500);
      }
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('[JobService.publishJob]:', error);
      throw new AppError('Failed to publish job', 500);
    }
  }

  /**
   * Close a job (set status to closed)
   */
  static async closeJob(id: string, userId: string): Promise<void> {
    try {
      const adminSupabase = createAdminClient();
      const { data: job, error: fetchError } = await adminSupabase
        .from('jobs')
        .select('status, client_profiles!inner(user_id)')
        .eq('id', id)
        .single();
      if (fetchError || !job || (job as any).client_profiles?.user_id !== userId) {
        throw new AppError('Job not found', 404);
      }
      // Allow closing jobs that are open, in_review, hired
      const closeableStatuses = ['open', 'in_review', 'hired'];
      if (!closeableStatuses.includes(job.status as JobStatus)) {
        throw new AppError('Job cannot be closed in current status', 400);
      }
      const { error } = await adminSupabase
        .from('jobs')
        .update({ status: 'closed', updated_at: new Date().toISOString() })
        .eq('id', id);
      if (error) {
        console.error('[DB Error - Close Job]:', error);
        throw new AppError('Failed to close job', 500);
      }
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('[JobService.closeJob]:', error);
      throw new AppError('Failed to close job', 500);
    }
  }

  /**
   * Delete a job (set status to deleted)
   */
  static async deleteJob(id: string, userId: string): Promise<void> {
    try {
      const adminSupabase = createAdminClient();
      const { data: job, error: fetchError } = await adminSupabase
        .from('jobs')
        .select('status, client_profiles!inner(user_id)')
        .eq('id', id)
        .single();
      if (fetchError || !job || (job as any).client_profiles?.user_id !== userId) {
        throw new AppError('Job not found', 404);
      }
      // Only allow deletion of draft jobs
      if (job.status !== 'draft') {
        throw new AppError('Only draft jobs can be deleted', 400);
      }
      const { error } = await adminSupabase
        .from('jobs')
        .update({ status: 'deleted', updated_at: new Date().toISOString() })
        .eq('id', id);
      if (error) {
        console.error('[DB Error - Delete Job]:', error);
        throw new AppError('Failed to delete job', 500);
      }
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('[JobService.deleteJob]:', error);
      throw new AppError('Failed to delete job', 500);
    }
  }
}

/**
