   */
  static async getMessages(conversationId: string, page: number = 1, limit: number = 50): Promise<any[]> {
    try {
      const supabase = await createClient();

      // Get user
      const {
        data: { user },
      } = await supabase.auth.getUser();

      if (!user) {
        throw new UnauthorizedError('User not authenticated');
